<script>
 import {onMount} from 'svelte';import AssetTile from './AssetTile.svelte';import {assets} from '../stores/assets.svelte';import {selection} from '../stores/selection.svelte';import {shell,saveShell,navigate} from '../app/shell.svelte';import {editorUrl} from '../lib/router.ts';import {gridGeometry,visibleRange,indicesInRect} from '../lib/virtual-grid.ts';
 let {ids=[],onmenu=()=>{},onopen=id=>navigate(editorUrl(id))}=$props();let root,width=$state(800),height=$state(600),scrollTop=$state(0),drag=$state(null),frame=0,pendingScroll=0;
 const geometry=$derived(gridGeometry(width,shell.gridSize,shell.view==='list')),range=$derived(visibleRange(ids.length,scrollTop,height,geometry)),visible=$derived(ids.slice(range.start,range.end)),selected=$derived(new Set(selection.selectedIds));
 function click(event,id){if(event.shiftKey)selection.range(id,event.ctrlKey||event.metaKey);else if(event.ctrlKey||event.metaKey)selection.toggle(id);else selection.set([id]);}
 function scrolled(){pendingScroll=root.scrollTop;if(!frame)frame=requestAnimationFrame(()=>{frame=0;scrollTop=pendingScroll;});}
 function point(event){const rect=root.getBoundingClientRect();return{x:event.clientX-rect.left,y:event.clientY-rect.top+root.scrollTop};}
 function down(event){if(event.button!==0||event.target.closest('.asset-tile'))return;const p=point(event);drag={start:p,current:p,base:event.ctrlKey||event.metaKey?[...selection.selectedIds]:[],pointer:event.pointerId,moved:false};root.setPointerCapture(event.pointerId);if(!event.ctrlKey&&!event.metaKey)selection.clear();}
 function move(event){if(!drag||drag.pointer!==event.pointerId)return;const p=point(event);drag={...drag,current:p,moved:Math.abs(p.x-drag.start.x)+Math.abs(p.y-drag.start.y)>4};if(!drag.moved)return;const rect={left:Math.min(p.x,drag.start.x),right:Math.max(p.x,drag.start.x),top:Math.min(p.y,drag.start.y),bottom:Math.max(p.y,drag.start.y)};selection.set([...new Set([...drag.base,...indicesInRect(ids.length,rect,geometry).map(index=>ids[index])])]);}
 function wheel(event){if(!event.ctrlKey)return;event.preventDefault();event.stopPropagation();const sizes=[120,160,200],index=sizes.indexOf(shell.gridSize);shell.gridSize=sizes[Math.max(0,Math.min(2,index+(event.deltaY<0?1:-1)))];saveShell();}
 onMount(()=>{const observer=new ResizeObserver(entries=>{const rect=entries[0].contentRect;width=rect.width;height=rect.height;});observer.observe(root);root.addEventListener('wheel',wheel,{passive:false});return()=>{observer.disconnect();root.removeEventListener('wheel',wheel);cancelAnimationFrame(frame);};});
</script>
<!-- svelte-ignore a11y_no_noninteractive_element_interactions (Pointer rectangle selection, with keyboard equivalents registered centrally.) -->
<div class="asset-grid-scroll" bind:this={root} role="listbox" aria-label="素材网格" aria-multiselectable="true" tabindex="-1" onscroll={scrolled} onpointerdown={down} onpointermove={move} onpointerup={()=>drag=null} onpointercancel={()=>drag=null}>
 <div class="asset-grid-space" style:height={`${range.height+geometry.padding*2}px`}>
 {#each visible as id,index (id)}{@const position=range.start+index}{#if assets.index[id]}<div class="asset-grid-cell" style:left={`${geometry.padding+position%geometry.columns*(geometry.cellWidth+geometry.gap)}px`} style:top={`${geometry.padding+Math.floor(position/geometry.columns)*geometry.rowHeight}px`} style:width={`${geometry.cellWidth}px`} style:height={`${geometry.rowHeight-geometry.gap}px`}><AssetTile asset={assets.index[id]} selected={selected.has(id)} size={shell.gridSize} list={shell.view==='list'} onclick={click} {onopen} {onmenu}/></div>{/if}{/each}
 {#if drag?.moved}<div class="selection-rectangle" style:left={`${Math.min(drag.start.x,drag.current.x)}px`} style:top={`${Math.min(drag.start.y,drag.current.y)}px`} style:width={`${Math.abs(drag.start.x-drag.current.x)}px`} style:height={`${Math.abs(drag.start.y-drag.current.y)}px`}></div>{/if}
 </div>
</div>
<style>.asset-grid-scroll{position:relative;min-height:0;overflow:auto;overscroll-behavior:contain;touch-action:none;background:var(--bg);scrollbar-gutter:stable}.asset-grid-space{position:relative;min-height:100%;user-select:none}.asset-grid-cell{position:absolute;contain:layout style}.selection-rectangle{position:absolute;z-index:3;pointer-events:none;border:1px solid var(--accent);background:var(--accent-soft);box-sizing:border-box}</style>
